#include <Core/IO/SIRIOBufferPool.h>
#include <stdint.h>
SIRIOBufferPool::SIRIOBufferPool( void ) noexcept : m_pStorage( nullptr ), m_nCapacity( 0 ), m_nUsed( 0 ), m_pSlots( nullptr ), m_nSlotCapacity( 0 ), m_nMaxAlignment( 0 ), m_bInitialized( false ) {}
sirIOResult_t SIRIOBufferPool::initialize( const sirIOBufferPoolConfig_t& c ) noexcept { if ( m_bInitialized || c.pStorage == nullptr || c.pLeaseStorage == nullptr || c.nLeaseCapacity == 0 || c.nStorageBytes == 0 || c.nMaxAlignment == 0 ) return SIR_IO_INVALID_ARGUMENT; m_pStorage = static_cast<uint8_t *>( c.pStorage ); m_nCapacity = c.nStorageBytes; m_pSlots = c.pLeaseStorage; m_nSlotCapacity = c.nLeaseCapacity; m_nMaxAlignment = c.nMaxAlignment; for ( uint32_t i=0;i<m_nSlotCapacity;++i ) m_pSlots[i] = {}; m_bInitialized=true; return SIR_IO_OK; }
sirIOResult_t SIRIOBufferPool::acquire( uint64_t nBytes, uint32_t nAlignment, sirIOBufferLease_t *pLease ) noexcept { if (!m_bInitialized||pLease==nullptr||nBytes==0||nAlignment==0||(nAlignment&(nAlignment-1))!=0||nAlignment>m_nMaxAlignment)return SIR_IO_INVALID_ARGUMENT; uint64_t nOffset=0; for (;;) { nOffset=(nOffset+nAlignment-1)&~(static_cast<uint64_t>(nAlignment)-1); uint64_t nNext=nOffset+nBytes; if(nNext>m_nCapacity)break; bool bMoved=false; for(uint32_t i=0;i<m_nSlotCapacity;++i)if(m_pSlots[i].bytes.pData!=nullptr){uint64_t nStart=static_cast<uint64_t>(m_pSlots[i].bytes.pData-m_pStorage);uint64_t nEnd=nStart+m_pSlots[i].bytes.nSize;if(nOffset<nEnd&&nStart<nNext){nOffset=nEnd;bMoved=true;break;}} if(!bMoved){for(uint32_t i=0;i<m_nSlotCapacity;++i)if(m_pSlots[i].bytes.pData==nullptr){m_pSlots[i].handle={i,m_pSlots[i].handle.nGeneration+1};m_pSlots[i].bytes={m_pStorage+nOffset,nBytes};*pLease=m_pSlots[i];m_nUsed+=nBytes;return SIR_IO_OK;}return SIR_IO_OUT_OF_CAPACITY;} } return SIR_IO_OUT_OF_CAPACITY; }
sirIOResult_t SIRIOBufferPool::release( sirIOBufferHandle_t h ) noexcept { if(!m_bInitialized||h.nSlot>=m_nSlotCapacity||m_pSlots[h.nSlot].handle.nGeneration!=h.nGeneration||m_pSlots[h.nSlot].bytes.pData==nullptr)return SIR_IO_STALE_HANDLE;m_nUsed-=m_pSlots[h.nSlot].bytes.nSize;m_pSlots[h.nSlot].bytes={};return SIR_IO_OK; }
uint64_t SIRIOBufferPool::getCapacity( void ) const noexcept{return m_nCapacity;} uint64_t SIRIOBufferPool::getUsedBytes( void ) const noexcept{return m_nUsed;}
sirIOResult_t SIRIOBufferPool::shutdown( void ) noexcept { if(!m_bInitialized)return SIR_IO_OK;for(uint32_t i=0;i<m_nSlotCapacity;++i)if(m_pSlots[i].bytes.pData!=nullptr)return SIR_IO_BUSY;m_bInitialized=false;m_pStorage=nullptr;m_nCapacity=m_nUsed=0;m_nMaxAlignment=0;return SIR_IO_OK; }
